img = imread("sampleTumor.jpg");

imgGs = imresize(imadjust(im2gray(img)),[512 512]);
%%
imgBin = imclearborder(imbinarize(imgGs,"adaptive",ForegroundPolarity="bright"));

%imshow(imgBin)
%%
h = fspecial('average', [7 7]);
imgFiltered = imfilter(imgBin,h,"replicate");
%imshow(imgFiltered);
%%
closed  = imclose(imgFiltered, strel('disk', 3));
brain   = bwareafilt(imfill(closed, 'holes'), 1);
inner  = imerode(brain, strel('disk', 20));

border = imgFiltered & brain & ~inner;
%imshow(border)
%%
imgDef = imgFiltered - border;
%imshow(imgDef)
%%
D = bwdist(~imgDef); % convert back to grayscale
D = D / max(D(:));
%%
CC = bwconncomp(imgDef);
s  = regionprops(CC, 'Solidity');
S  = zeros(size(imgDef));
for k = 1:CC.NumObjects
    S(CC.PixelIdxList{k}) = s(k).Solidity;
end

emph = D .* S;% thick AND solid -> bright
%%
emphSum = sum(emph,2);

maxIndices = islocalmax(emphSum);
%%
idx  = find(maxIndices);          % positions of all local maxima
vals = emphSum(idx);                    % their heights

[gMax, k] = max(vals);            % the global max among them
others = vals;
others(k) = [];                   % every other local max

maxIndices = false(size(emphSum));      % start with no peaks kept
if isempty(others) || gMax - max(others) >= 10
    maxIndices(idx(k)) = true;    % keep the global max only if it clears the 25-unit gap
end

imshow(img) %[output:7cae53ba]
isTumor = nnz(maxIndices) == 1  %[output:9bae223f]

